# Success and idempotent rerun
calls = []
def execute_ok(step):
    calls.append(('do', step))
def compensate_ok(step):
    calls.append(('undo', step))
journal = {}
engine = SagaOrchestrator(execute_ok, compensate_ok, journal=journal)
assert engine.journal is journal
assert engine.run('s1', ['reserve', 'charge', 'ship']) == 'completed'
assert calls == [('do', 'reserve'), ('do', 'charge'), ('do', 'ship')]
assert engine.run('s1', ['reserve', 'charge', 'ship']) == 'completed'
assert len(calls) == 3

# Retry succeeds on the third total attempt when max_retries=2
attempts = {'charge': 0}
def execute_retry(step):
    if step == 'charge':
        attempts[step] += 1
        if attempts[step] < 3:
            raise RetryableError('temporary')
retry_engine = SagaOrchestrator(execute_retry, lambda step: None, max_retries=2)
assert retry_engine.run('s2', ['reserve', 'charge']) == 'completed'
assert attempts['charge'] == 3

# Fatal failure compensates in reverse order
trace = []
def execute_fatal(step):
    trace.append(('do', step))
    if step == 'ship':
        raise FatalError('carrier rejected')
def compensate_trace(step):
    trace.append(('undo', step))
fatal_engine = SagaOrchestrator(execute_fatal, compensate_trace)
assert fatal_engine.run('s3', ['reserve', 'charge', 'ship']) == 'compensated'
assert trace == [('do', 'reserve'), ('do', 'charge'), ('do', 'ship'), ('undo', 'charge'), ('undo', 'reserve')]

# Forward crash persists completed steps and recovery does not repeat them
trace = []
crashed = {'done': False}
def execute_crash(step):
    trace.append(('do', step))
    if step == 'charge' and not crashed['done']:
        crashed['done'] = True
        raise CrashError('process died')
shared = {}
first = SagaOrchestrator(execute_crash, lambda step: trace.append(('undo', step)), journal=shared)
try:
    first.run('s4', ['reserve', 'charge', 'ship'])
    assert False, 'CrashError must propagate'
except CrashError:
    pass
second = SagaOrchestrator(execute_crash, lambda step: trace.append(('undo', step)), journal=shared)
assert second.recover('s4', ['reserve', 'charge', 'ship']) == 'completed'
assert trace.count(('do', 'reserve')) == 1
assert trace.count(('do', 'charge')) == 2
assert trace.count(('do', 'ship')) == 1

# Compensation crash resumes compensation without forward execution
trace = []
comp_crashed = {'done': False}
def execute_for_comp(step):
    trace.append(('do', step))
    if step == 'c':
        raise FatalError('fail')
def crashing_comp(step):
    trace.append(('undo', step))
    if step == 'b' and not comp_crashed['done']:
        comp_crashed['done'] = True
        raise CrashError('during compensation')
shared_comp = {}
comp_engine = SagaOrchestrator(execute_for_comp, crashing_comp, journal=shared_comp)
try:
    comp_engine.run('s5', ['a', 'b', 'c'])
    assert False, 'compensation crash must propagate'
except CrashError:
    pass
recovered = SagaOrchestrator(execute_for_comp, crashing_comp, journal=shared_comp)
assert recovered.recover('s5', ['a', 'b', 'c']) == 'compensated'
assert trace.count(('do', 'a')) == 1 and trace.count(('do', 'b')) == 1 and trace.count(('do', 'c')) == 1
assert trace.count(('undo', 'a')) == 1
assert trace.count(('undo', 'b')) == 2

try:
    recovered.run('s5', ['a', 'DIFFERENT'])
    assert False, 'changed plan must be rejected'
except ValueError:
    pass

print('Crash-recoverable saga tests passed.')
